import{_ as t,o,c as a,ag as r}from"./chunks/framework.8tqBsFWt.js";const p=JSON.parse('{"title":"Intent Classification Spike","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/intent-classification-spike.md","filePath":"decisions/intent-classification-spike.md"}'),s={name:"decisions/intent-classification-spike.md"};function i(n,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="intent-classification-spike" tabindex="-1">Intent Classification Spike <a class="header-anchor" href="#intent-classification-spike" aria-label="Permalink to &quot;Intent Classification Spike&quot;">​</a></h1><p><strong>Status:</strong> draft for review against RFC #654 <strong>Date:</strong> 2026-05-16 <strong>Purpose:</strong> validate the architecture proposed in #654 before any code is written. Walk a verb-context table through every manual-test scenario; identify gaps; render a verdict on whether the deterministic approach holds.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p><strong>In scope:</strong></p><ul><li>Verb/preposition patterns for the highest-frequency tools (<code>create_project</code>, <code>create_client</code>, <code>log_time</code>, <code>allocate_hours</code>, <code>assign_pm</code>, <code>set_rate</code>, <code>create_liability</code>, rename/archive verbs).</li><li>Pronoun resolution via conversation-history scan.</li><li>Token-boundary strategy when names are unquoted.</li></ul><p><strong>Out of scope:</strong></p><ul><li>Implementation. No code is written in this spike.</li><li>Response generation (prompt slimming, paraphrase format).</li><li>Intent classification beyond entity extraction. Phase 3 (full intent classification with proposed-params block) is a follow-up exercise once Phase 1 is proven.</li><li>Telemetry design.</li></ul><h2 id="approach" tabindex="-1">Approach <a class="header-anchor" href="#approach" aria-label="Permalink to &quot;Approach&quot;">​</a></h2><p>For each candidate verb pattern, define:</p><ol><li><strong>Trigger</strong> — the regex/keyword that starts the pattern.</li><li><strong>Slot map</strong> — for each prepositional phrase, what entity type goes there.</li><li><strong>DB resolution rules</strong> — how to handle exact match, ambiguous match, no match.</li><li><strong>Failure mode</strong> — what annotation is emitted when a slot can&#39;t be filled.</li></ol><p>Then walk every row of the RFC&#39;s 12-row manual-test matrix through the table. Score each row as ✓ (clean), ⚠️ (works but reveals a required capability), or ✗ (architecture cannot express this — go back to the drawing board).</p><h2 id="the-verb-context-table-v0" tabindex="-1">The verb-context table (v0) <a class="header-anchor" href="#the-verb-context-table-v0" aria-label="Permalink to &quot;The verb-context table (v0)&quot;">​</a></h2><p>This is the artifact the implementation phase would translate into code. The table is deliberately exhaustive about which <strong>preposition + verb</strong> combinations mean which entity type, because the same preposition (<code>for</code>, <code>to</code>, <code>on</code>) means different things in different verbs. That ambiguity is the structural bug we&#39;re solving — making it explicit in a table is the entire point.</p><h3 id="create-project" tabindex="-1"><code>create_project</code> <a class="header-anchor" href="#create-project" aria-label="Permalink to &quot;`create_project`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Trigger</th><th>Pattern</th><th>Slot</th><th>Type</th></tr></thead><tbody><tr><td><code>create [a]? [TYPE]? project [NAME]</code></td><td>after <code>create [...]project</code> up to <code>for</code>/<code>as</code>/<code>due</code>/<code>,</code></td><td><code>NAME</code></td><td><code>project_name</code></td></tr><tr><td>... <code>for [X]</code></td><td>after <code>for</code> up to <code>as</code>/<code>due</code>/<code>,</code>/<code>—</code>/end</td><td><code>X</code></td><td><code>client_name</code></td></tr><tr><td>... <code>as [Y]</code></td><td>after <code>as</code> up to next boundary</td><td><code>Y</code></td><td><code>project_type</code> (match against canonical set)</td></tr><tr><td>... <code>[N]h</code> or <code>[N] hours</code></td><td>numeric + unit</td><td><code>N</code></td><td><code>hours_budget</code></td></tr><tr><td>... <code>$[N]</code></td><td>dollar sign + number</td><td><code>N</code></td><td><code>contract_value</code></td></tr><tr><td>... <code>due [DATE]</code></td><td>after <code>due</code></td><td><code>DATE</code></td><td><code>deadline</code></td></tr></tbody></table><p>Boundary words for project_name extraction: <code>for</code>, <code>as</code>, <code>due</code>, <code>,</code>, <code>;</code>, <code>—</code>, <code>at</code>, <code>with</code>, end-of-string.</p><h3 id="create-client" tabindex="-1"><code>create_client</code> <a class="header-anchor" href="#create-client" aria-label="Permalink to &quot;`create_client`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Trigger</th><th>Pattern</th><th>Slot</th><th>Type</th></tr></thead><tbody><tr><td><code>create [a]? client [NAME]</code> or <code>add [a]? client [NAME]</code></td><td>after <code>client</code> up to end / <code>,</code></td><td><code>NAME</code></td><td><code>client_name</code></td></tr></tbody></table><h3 id="log-time" tabindex="-1"><code>log_time</code> <a class="header-anchor" href="#log-time" aria-label="Permalink to &quot;`log_time`&quot;">​</a></h3><p><strong>Verb aliases (normalised at extraction — see Q3):</strong> <code>log</code> | <code>track</code> | <code>record</code>. Paraphrase always uses <code>log</code>.</p><table tabindex="0"><thead><tr><th>Trigger</th><th>Pattern</th><th>Slot</th><th>Type</th></tr></thead><tbody><tr><td><code>log [N]h</code> or <code>log [N] hours</code></td><td>numeric + unit</td><td><code>N</code></td><td><code>hours</code></td></tr><tr><td>... <code>of [TASK]</code> or <code>on [TASK]</code></td><td>after <code>of</code>/<code>on</code> up to next prep / EOS</td><td><code>TASK</code></td><td><code>task_name</code></td></tr><tr><td>... <code>to [Y]</code></td><td>after <code>to</code> up to next prep / EOS</td><td><code>Y</code></td><td><code>project_name</code></td></tr><tr><td>... <code>for [Z]</code></td><td>after <code>for</code> up to next prep / EOS</td><td><code>Z</code></td><td><code>user_name</code> (target person — defaults to current user if absent)</td></tr><tr><td>... <code>[on/for]? [DATE]</code></td><td>recognised date or weekday</td><td><code>DATE</code></td><td><code>date</code> (defaults to today)</td></tr></tbody></table><p><strong>Note (#729):</strong> <code>on</code> is a <code>task_name</code> preposition. The natural phrasing <code>to &lt;project&gt; on &lt;task&gt;</code> routes correctly: <code>to</code> → project_name, <code>on</code> → task_name. The legacy single-preposition form <code>log Xh on &lt;project&gt;</code> (no <code>to</code>) now lands in task_name rather than project_name; the resolver&#39;s missing-slot flow guides the user to supply a project.</p><p><strong>Critical:</strong> for <code>log_time</code>, <code>for X</code> is a <strong>user</strong>, not a client. This is the inverse of <code>create_project</code>. The table makes the per-verb distinction explicit; the resolver must dispatch on verb, not just preposition.</p><h3 id="allocate-hours" tabindex="-1"><code>allocate_hours</code> <a class="header-anchor" href="#allocate-hours" aria-label="Permalink to &quot;`allocate_hours`&quot;">​</a></h3><p>Two surface forms share the same verb:</p><p><strong>Pattern A — named user</strong> (no pronoun before hours):</p><table tabindex="0"><thead><tr><th>Trigger</th><th>Pattern</th><th>Slot</th><th>Type</th></tr></thead><tbody><tr><td><code>allocate [N]h</code></td><td>numeric + unit</td><td><code>N</code></td><td><code>hours</code></td></tr><tr><td>... <code>to [Z]</code></td><td>after <code>to</code>, stops at <code>on</code>/<code>for</code></td><td><code>Z</code></td><td><code>user_name</code></td></tr><tr><td>... <code>for [TASK]</code> or <code>as [TASK]</code></td><td>after <code>for</code>/<code>as</code></td><td><code>TASK</code></td><td><code>task_name</code></td></tr><tr><td>... <code>on [P]</code></td><td>after <code>on</code></td><td><code>P</code></td><td><code>project_name</code></td></tr></tbody></table><p><strong>Pattern B — pronoun before hours</strong> (<code>allocate &lt;pronoun&gt; &lt;hours&gt; to &lt;project&gt; on &lt;task&gt;</code>):</p><table tabindex="0"><thead><tr><th>Trigger</th><th>Pattern</th><th>Slot</th><th>Type</th></tr></thead><tbody><tr><td><code>allocate [pronoun] [N]h</code></td><td>bare pronoun before hours token</td><td>pronoun</td><td><code>user_name</code> (is_pronoun=true)</td></tr><tr><td>... <code>to [P]</code></td><td>after <code>to</code> (first occurrence), stops at <code>on</code>/<code>for</code></td><td><code>P</code></td><td><code>project_name</code></td></tr><tr><td>... <code>on [TASK]</code></td><td>after <code>on</code></td><td><code>TASK</code></td><td><code>task_name</code></td></tr></tbody></table><p>The extractor detects pattern B by scanning the message between the verb alias end and the hours token for a word in <code>PRONOUNS</code>. If found, the pronoun fills <code>user_name</code> and downstream slots re-route: <code>project_name</code> uses <code>to</code> (first occurrence wins), <code>task_name</code> accepts <code>on</code>.</p><p>Again, <code>for</code> means task, not client. Per-verb dispatch matters.</p><h3 id="assign-pm" tabindex="-1"><code>assign_pm</code> <a class="header-anchor" href="#assign-pm" aria-label="Permalink to &quot;`assign_pm`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Trigger</th><th>Pattern</th><th>Slot</th><th>Type</th></tr></thead><tbody><tr><td><code>assign [Z] as PM</code></td><td>after <code>assign</code>, before <code>as</code></td><td><code>Z</code></td><td><code>user_name</code></td></tr><tr><td>... <code>to [P]</code> or <code>on [P]</code></td><td>after <code>to</code>/<code>on</code></td><td><code>P</code></td><td><code>project_name</code></td></tr></tbody></table><h3 id="set-rate" tabindex="-1"><code>set_rate</code> <a class="header-anchor" href="#set-rate" aria-label="Permalink to &quot;`set_rate`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Trigger</th><th>Pattern</th><th>Slot</th><th>Type</th></tr></thead><tbody><tr><td><code>set rate for [Z]</code></td><td>after <code>for</code></td><td><code>Z</code></td><td><code>user_name</code></td></tr><tr><td>... <code>to $[N]</code></td><td>after <code>to</code></td><td><code>N</code></td><td>rate value</td></tr></tbody></table><h3 id="create-liability" tabindex="-1"><code>create_liability</code> <a class="header-anchor" href="#create-liability" aria-label="Permalink to &quot;`create_liability`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Trigger</th><th>Pattern</th><th>Slot</th><th>Type</th></tr></thead><tbody><tr><td><code>create [a]? liability for [V]</code></td><td>after <code>for</code>, before <code>on</code></td><td><code>V</code></td><td><code>vendor_name</code> (user, vendor type only)</td></tr><tr><td>... <code>on [P]</code></td><td>after <code>on</code></td><td><code>P</code></td><td><code>project_name</code></td></tr><tr><td>... <code>for $[N]</code> or <code>at $[N]</code></td><td>dollar amount</td><td><code>N</code></td><td><code>agreed_amount</code></td></tr><tr><td>... <code>over [N]h</code> or <code>[N] hours</code></td><td>hours value</td><td><code>N</code></td><td><code>agreed_hours</code></td></tr></tbody></table><h3 id="rename-archive" tabindex="-1"><code>rename_*</code> / <code>archive_*</code> <a class="header-anchor" href="#rename-archive" aria-label="Permalink to &quot;`rename_*` / `archive_*`&quot;">​</a></h3><p>These verbs need an object type because the same word (&quot;Acme&quot;) could be a client name, project name, task name, or user surname. Two resolution paths:</p><ol><li><strong>Explicit type given</strong> (&quot;archive the design <em>task</em>&quot;, &quot;rename <em>project</em> X to Y&quot;) → trivial: take the object type literally, resolve in that table.</li><li><strong>Pronoun or bare reference</strong> (&quot;rename it to Y&quot;, &quot;archive Acme&quot;) → server scans conversation history for the most-recent matching entity. Multiple matches across types → emit an ambiguous annotation; Claude presents a typed dialing menu.</li></ol><h3 id="pronouns-cross-verb" tabindex="-1">Pronouns (cross-verb) <a class="header-anchor" href="#pronouns-cross-verb" aria-label="Permalink to &quot;Pronouns (cross-verb)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pronoun</th><th>Default expected type</th><th>Notes</th></tr></thead><tbody><tr><td><code>it</code></td><td>most-recently-mentioned project or client (by verb context)</td><td>If verb expects a user (<code>assign her</code>), <code>it</code> is wrong type — emit ambiguous</td></tr><tr><td><code>them</code>, <code>they</code></td><td>inferred from verb: <code>allocate to them</code> → user; <code>create project for them</code> → client</td><td></td></tr><tr><td><code>him</code>, <code>her</code>, <code>his</code></td><td>user (gendered pronouns imply person)</td><td></td></tr><tr><td><code>their</code></td><td>possessive — passes through to the noun it modifies</td><td></td></tr></tbody></table><p>The server&#39;s pronoun-resolution algorithm:</p><ol><li>Identify the <strong>expected entity type</strong> from the verb/preposition slot.</li><li>Scan conversation history (last N turns, where N is bounded by the existing 24h window) for entities of that type.</li><li>If exactly one candidate of that type, resolve to it.</li><li>If multiple, emit a dialing-menu annotation typed to that entity.</li><li>If none, emit a &quot;no plausible referent — ask user to name explicitly&quot; annotation.</li></ol><h2 id="walkthrough-of-the-12-manual-test-scenarios" tabindex="-1">Walkthrough of the 12 manual-test scenarios <a class="header-anchor" href="#walkthrough-of-the-12-manual-test-scenarios" aria-label="Permalink to &quot;Walkthrough of the 12 manual-test scenarios&quot;">​</a></h2><p>For each row, the trace is: raw input → extractor output → resolver output → emitted annotation → expected Claude action.</p><hr><h3 id="row-1-create-project-rando-site-for-smithsonian-as-t-m-40h-due-2026-12-01" tabindex="-1">Row 1: <code>&quot;Create project Rando Site for Smithsonian as T&amp;M, 40h, due 2026-12-01&quot;</code> <a class="header-anchor" href="#row-1-create-project-rando-site-for-smithsonian-as-t-m-40h-due-2026-12-01" aria-label="Permalink to &quot;Row 1: `&quot;Create project Rando Site for Smithsonian as T&amp;M, 40h, due 2026-12-01&quot;`&quot;">​</a></h3><p><strong>Extractor:</strong></p><ul><li>verb: <code>create_project</code></li><li>project_name: <code>&quot;Rando Site&quot;</code> (between <code>project</code> and <code>for</code>)</li><li>client_name: <code>&quot;Smithsonian&quot;</code> (between <code>for</code> and <code>as</code>)</li><li>project_type: <code>&quot;T&amp;M&quot;</code> (between <code>as</code> and <code>,</code>)</li><li>hours_budget: <code>40</code></li><li>deadline: <code>2026-12-01</code></li></ul><p><strong>Resolver:</strong></p><ul><li><code>Smithsonian</code> → look up in clients table → not found → <strong>auto-create permitted on this verb</strong> (matches existing <code>findOrCreateClient</code> behaviour in <code>mcp-server.js</code>).</li><li><code>T&amp;M</code> matches canonical project_type set.</li></ul><p><strong>Annotation:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Pre-resolved: verb=create_project, project_name=&quot;Rando Site&quot;, client_name=&quot;Smithsonian&quot;, project_type=&quot;T&amp;M&quot;, hours_budget=40, deadline=&quot;2026-12-01&quot;. side_effects: [&quot;client \\&quot;Smithsonian\\&quot; will be auto-created (not found in clients table)&quot;]. All required params present. Call create_project with these values after confirmation paraphrase. The paraphrase MUST surface the auto-create side effect.]</span></span></code></pre></div><p><strong>Verdict:</strong> ✓ clean <em>if</em> the requesting user is an Owner or Manager with <code>create_client</code> permission. Per Q1, the confirmation paraphrase must read along the lines of &quot;I&#39;ll create a new client <em>Smithsonian</em>, then create a T&amp;M project <em>Rando Site</em> for them — 40h budget, due 2026-12-01&quot; so the user sees the client creation and can cancel if they meant an existing client whose name they got slightly wrong. If the requesting user is a User (no <code>create_client</code> permission), the resolver falls through to capability B and emits a missing-client annotation with a menu of existing clients — see capability D for the full rule.</p><hr><h3 id="row-2-create-project-rando-site-for-client-smithsonian-as-t-m" tabindex="-1">Row 2: <code>&#39;Create project Rando Site for client &quot;Smithsonian&quot; as T&amp;M…&#39;</code> <a class="header-anchor" href="#row-2-create-project-rando-site-for-client-smithsonian-as-t-m" aria-label="Permalink to &quot;Row 2: `&#39;Create project Rando Site for client &quot;Smithsonian&quot; as T&amp;M…&#39;`&quot;">​</a></h3><p>Same as Row 1. The literal <code>client &quot;...&quot;</code> is a hint that reinforces the type but doesn&#39;t change extraction — the boundary parser already lands on <code>Smithsonian</code> regardless. Worth keeping the explicit form working as a fallback for users who want to be unambiguous.</p><p><strong>Verdict:</strong> ✓ clean.</p><hr><h3 id="row-3-log-2-hours-of-design-to-it-preceding-turn-established-project-rando-site" tabindex="-1">Row 3: <code>&quot;log 2 hours of design to it&quot;</code> (preceding turn established project &quot;Rando Site&quot;) <a class="header-anchor" href="#row-3-log-2-hours-of-design-to-it-preceding-turn-established-project-rando-site" aria-label="Permalink to &quot;Row 3: `&quot;log 2 hours of design to it&quot;` (preceding turn established project &quot;Rando Site&quot;)&quot;">​</a></h3><p><strong>Extractor:</strong></p><ul><li>verb: <code>log_time</code></li><li>hours: <code>2</code></li><li>task_name: <code>&quot;design&quot;</code></li><li>project: pronoun <code>&quot;it&quot;</code>, expected type = project (from <code>to [Y]</code> slot for log_time)</li></ul><p><strong>Resolver:</strong></p><ul><li>Scan history for most-recent project → <code>Rando Site</code> (one turn back).</li><li>Task <code>design</code> → look up in tasks table → matches <code>Design</code> (or returns dialing menu if multiple disciplines have a <code>Design</code> task).</li></ul><p><strong>Annotation:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Pre-resolved: verb=log_time, hours=2, task_name=&quot;Design&quot; (matched exactly), project_name=&quot;Rando Site&quot; (pronoun &quot;it&quot; resolved from prior turn), user_name=self, date=today. Call log_time after confirmation.]</span></span></code></pre></div><p><strong>Verdict:</strong> ✓ clean.</p><hr><h3 id="row-4-allocate-hours-to-them-no-user-has-been-named-in-the-conversation" tabindex="-1">Row 4: <code>&quot;allocate hours to them&quot;</code> (no user has been named in the conversation) <a class="header-anchor" href="#row-4-allocate-hours-to-them-no-user-has-been-named-in-the-conversation" aria-label="Permalink to &quot;Row 4: `&quot;allocate hours to them&quot;` (no user has been named in the conversation)&quot;">​</a></h3><p><strong>Extractor:</strong></p><ul><li>verb: <code>allocate_hours</code></li><li>hours: <strong>missing</strong> (no number before <code>hours</code>)</li><li>user: pronoun <code>&quot;them&quot;</code>, expected type = user</li></ul><p><strong>Resolver:</strong></p><ul><li>Scan history for most-recent user → none.</li><li>hours value missing.</li></ul><p><strong>Annotation:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Pre-resolved: verb=allocate_hours, MISSING user_name (pronoun &quot;them&quot; found no user referent in last 24h), MISSING hours value. Stop and ask the user to name the recipient and the number of hours.]</span></span></code></pre></div><p><strong>Verdict:</strong> ✓ clean. This is precisely the case the v2 fix tried and failed to handle in the prompt; the deterministic resolver handles it cleanly.</p><hr><h3 id="row-5-allocate-10h-to-alice-for-design-on-rando-site" tabindex="-1">Row 5: <code>&quot;allocate 10h to @alice for design on Rando Site&quot;</code> <a class="header-anchor" href="#row-5-allocate-10h-to-alice-for-design-on-rando-site" aria-label="Permalink to &quot;Row 5: `&quot;allocate 10h to @alice for design on Rando Site&quot;`&quot;">​</a></h3><p><strong>Extractor:</strong></p><ul><li>verb: <code>allocate_hours</code></li><li>hours: <code>10</code></li><li>user: <code>@alice</code> (mention)</li><li>task_name: <code>&quot;design&quot;</code></li><li>project_name: <code>&quot;Rando Site&quot;</code></li></ul><p><strong>Resolver:</strong></p><ul><li><code>@alice</code> → resolve Slack mention to user record.</li><li><code>design</code> → tasks table.</li><li><code>Rando Site</code> → projects table.</li></ul><p><strong>Annotation:</strong> standard pre-resolved block with all four slots filled.</p><p><strong>Verdict:</strong> ✓ clean.</p><hr><h3 id="row-6-set-rate-for-sarah-to-150" tabindex="-1">Row 6: <code>&quot;set rate for Sarah to $150&quot;</code> <a class="header-anchor" href="#row-6-set-rate-for-sarah-to-150" aria-label="Permalink to &quot;Row 6: `&quot;set rate for Sarah to $150&quot;`&quot;">​</a></h3><p><strong>Extractor:</strong></p><ul><li>verb: <code>set_rate</code></li><li>user_name: <code>&quot;Sarah&quot;</code></li><li>rate: <code>150</code></li></ul><p><strong>Resolver:</strong></p><ul><li><code>Sarah</code> → users table. If multiple <code>Sarah</code>s, dialing menu.</li></ul><p><strong>Annotation:</strong> standard pre-resolved with potential dialing-menu fallback.</p><p><strong>Verdict:</strong> ✓ clean.</p><hr><h3 id="row-7-log-4h-of-dev-to-nike-on-tuesday" tabindex="-1">Row 7: <code>&quot;log 4h of dev to Nike on Tuesday&quot;</code> <a class="header-anchor" href="#row-7-log-4h-of-dev-to-nike-on-tuesday" aria-label="Permalink to &quot;Row 7: `&quot;log 4h of dev to Nike on Tuesday&quot;`&quot;">​</a></h3><p><strong>Extractor:</strong></p><ul><li>verb: <code>log_time</code></li><li>hours: <code>4</code></li><li>task_name: <code>&quot;dev&quot;</code> (alias — resolver maps to <code>Development</code>)</li><li>project_name: <code>&quot;Nike&quot;</code></li><li>date: <code>&quot;Tuesday&quot;</code></li></ul><p><strong>Resolver:</strong></p><ul><li><code>Nike</code> → projects table. Note: if a user is also named <code>Nike</code> it doesn&#39;t matter because the verb-context says this slot is a project. <strong>This is exactly the inversion the current prompt gets wrong.</strong></li><li><code>Tuesday</code> → date module. Must resolve to the <em>most recent past</em> Tuesday (logging is retroactive). If today is Tuesday, today.</li></ul><p><strong>Annotation:</strong> standard.</p><p><strong>Verdict:</strong> ⚠️ clean, but reveals a required capability:</p><blockquote><p><strong>Required capability A:</strong> date-resolution submodule. &quot;Monday&quot;, &quot;Tuesday&quot;, &quot;yesterday&quot;, &quot;last Friday&quot; all need deterministic resolution rules. For logging verbs, weekday names default to the most recent past occurrence; this is consistent with existing prompt rule at lines 568+ but must be enforced in code, not prose.</p></blockquote><hr><h3 id="row-8-assign-mark-as-pm-no-project-mentioned" tabindex="-1">Row 8: <code>&quot;assign Mark as PM&quot;</code> (no project mentioned) <a class="header-anchor" href="#row-8-assign-mark-as-pm-no-project-mentioned" aria-label="Permalink to &quot;Row 8: `&quot;assign Mark as PM&quot;` (no project mentioned)&quot;">​</a></h3><p><strong>Extractor:</strong></p><ul><li>verb: <code>assign_pm</code></li><li>user_name: <code>&quot;Mark&quot;</code> (as PM)</li><li>project: <strong>missing</strong></li></ul><p><strong>Resolver:</strong></p><ul><li><code>Mark</code> → users table.</li><li>Scan history for most-recent project → ideally one is found from prior turn; otherwise missing.</li></ul><p><strong>Annotation (project found in history):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Pre-resolved: verb=assign_pm, user_name=&quot;Mark&quot; (exact match, user_id=42), project_name=&quot;Rando Site&quot; (inferred from prior turn). Confirm with user before calling.]</span></span></code></pre></div><p><strong>Annotation (no project in history):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Pre-resolved: verb=assign_pm, user_name=&quot;Mark&quot; (exact match), MISSING project_name. Ask user which project.]</span></span></code></pre></div><p><strong>Verdict:</strong> ⚠️ clean with a required capability:</p><blockquote><p><strong>Required capability B:</strong> missing-required-param ask-and-stop annotation. Many verbs have required slots; if any are missing after extraction + history scan, emit a &quot;MISSING X — ask the user&quot; annotation rather than guessing. The prompt rule for required params (in <code>CREATING PROJECTS</code> etc.) collapses into one general capability.</p></blockquote><hr><h3 id="row-9-create-a-fixed-price-project-for-acme-—-50k-200h-due-2026-12-01" tabindex="-1">Row 9: <code>&#39;Create a fixed price project for Acme — $50k, 200h, due 2026-12-01&#39;</code> <a class="header-anchor" href="#row-9-create-a-fixed-price-project-for-acme-—-50k-200h-due-2026-12-01" aria-label="Permalink to &quot;Row 9: `&#39;Create a fixed price project for Acme — $50k, 200h, due 2026-12-01&#39;`&quot;">​</a></h3><p><strong>Extractor:</strong></p><ul><li>verb: <code>create_project</code></li><li>project_type: <code>&quot;Fixed Price&quot;</code> (from <code>[a fixed price] project</code>)</li><li>project_name: <strong>missing</strong> (user said &quot;a fixed price project&quot; with no name)</li><li>client_name: <code>&quot;Acme&quot;</code></li><li>contract_value: <code>50000</code></li><li>hours_budget: <code>200</code></li><li>deadline: <code>2026-12-01</code></li></ul><p><strong>Resolver:</strong></p><ul><li><code>Acme</code> → clients table → may not exist → auto-create permitted.</li></ul><p><strong>Annotation:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Pre-resolved: verb=create_project, project_type=&quot;Fixed Price&quot;, client_name=&quot;Acme&quot;, contract_value=50000, hours_budget=200, deadline=&quot;2026-12-01&quot;, MISSING project_name. Ask user what to call the project.]</span></span></code></pre></div><p><strong>Verdict:</strong> ⚠️ clean using capability B (missing-param ask).</p><hr><h3 id="row-10-log-time-for-john-on-acme-—-3h-design-monday" tabindex="-1">Row 10: <code>&quot;log time for John on Acme — 3h design Monday&quot;</code> <a class="header-anchor" href="#row-10-log-time-for-john-on-acme-—-3h-design-monday" aria-label="Permalink to &quot;Row 10: `&quot;log time for John on Acme — 3h design Monday&quot;`&quot;">​</a></h3><p><strong>Extractor (updated for #729):</strong></p><ul><li>verb: <code>log_time</code></li><li>user_name: <code>&quot;John&quot;</code> (<code>for [Z]</code> slot for log_time → user, not client)</li><li>task_name: <code>&quot;Acme&quot;</code> (<code>on [Y]</code> slot for log_time → task, not project — see #729)</li><li>hours: <code>3</code></li><li>date: <code>&quot;Monday&quot;</code> (date submodule → most recent past Monday)</li><li>project_name: <strong>missing</strong> (no <code>to</code> preposition in this message)</li></ul><p><strong>Resolver:</strong> standard lookups; project_name in missing[] will prompt the user to supply a project.</p><p><strong>Annotation:</strong> standard.</p><p><strong>Verdict:</strong> ✓ clean. <strong>This is the row that proves the verb-context table earns its keep:</strong> <code>for X</code> is a user under <code>log_time</code> and a client under <code>create_project</code>. The table makes the distinction; the prompt currently does not. Note: after #729, <code>on X</code> is task_name — the earlier analysis that <code>on X</code> = project_name was superseded by the smoke evidence in that issue.</p><hr><h3 id="row-11-rename-it-to-nike-sprint-two-preceding-turn-created-an-agile-sprint" tabindex="-1">Row 11: <code>&quot;rename it to Nike Sprint Two&quot;</code> (preceding turn created an Agile sprint) <a class="header-anchor" href="#row-11-rename-it-to-nike-sprint-two-preceding-turn-created-an-agile-sprint" aria-label="Permalink to &quot;Row 11: `&quot;rename it to Nike Sprint Two&quot;` (preceding turn created an Agile sprint)&quot;">​</a></h3><p><strong>Extractor:</strong></p><ul><li>verb: <code>rename</code></li><li>object: pronoun <code>&quot;it&quot;</code>, expected type ambiguous (could rename a project, task, client, etc.)</li></ul><p><strong>Resolver:</strong></p><ul><li>Scan history for most-recent entity of <em>any</em> renamable type → finds the just-created sprint (a project).</li><li>new_name: <code>&quot;Nike Sprint Two&quot;</code>.</li></ul><p><strong>Annotation:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Pre-resolved: verb=rename, target_type=project, project_name=&quot;&lt;sprint as created&gt;&quot;, new_name=&quot;Nike Sprint Two&quot; (pronoun &quot;it&quot; resolved from prior turn — most recent renamable entity). Call rename_project after confirmation.]</span></span></code></pre></div><p><strong>Verdict:</strong> ✓ clean, contingent on capability C:</p><blockquote><p><strong>Required capability C:</strong> the conversation-history scan must annotate each remembered entity with its type, so the resolver can match by type when the verb permits multiple types. Today&#39;s summary format in <code>09. Conversations</code> may not preserve this — the scan must run on a structured event log, not free-text summary. <strong>This is a pre-flight check before Phase 1 starts</strong> (already flagged in RFC #654).</p></blockquote><hr><h3 id="row-12-archive-the-design-task-multiple-disciplines-have-a-design-task-enabled" tabindex="-1">Row 12: <code>&quot;archive the design task&quot;</code> (multiple disciplines have a <code>Design</code> task enabled) <a class="header-anchor" href="#row-12-archive-the-design-task-multiple-disciplines-have-a-design-task-enabled" aria-label="Permalink to &quot;Row 12: `&quot;archive the design task&quot;` (multiple disciplines have a `Design` task enabled)&quot;">​</a></h3><p><strong>Extractor:</strong></p><ul><li>verb: <code>archive</code></li><li>target_type: <code>task</code> (explicit — <code>&quot;the design *task*&quot;</code>)</li><li>task_name: <code>&quot;design&quot;</code></li></ul><p><strong>Resolver:</strong></p><ul><li>Look up <code>design</code> in tasks table → multiple matches.</li></ul><p><strong>Annotation:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Pre-resolved: verb=archive, target_type=task, AMBIGUOUS task_name=&quot;design&quot; — matched 3 tasks:</span></span>\n<span class="line"><span>  1. Design (Design discipline)</span></span>\n<span class="line"><span>  2. Design (Brand discipline)</span></span>\n<span class="line"><span>  3. Design (UX discipline)</span></span>\n<span class="line"><span>Present this dialing menu to the user.]</span></span></code></pre></div><p><strong>Verdict:</strong> ✓ clean.</p><hr><h2 id="score-summary" tabindex="-1">Score summary <a class="header-anchor" href="#score-summary" aria-label="Permalink to &quot;Score summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Row</th><th>Verdict</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td>✓</td><td>The tonight-bug case. Resolves cleanly.</td></tr><tr><td>2</td><td>✓</td><td>Quoted-form fallback works identically.</td></tr><tr><td>3</td><td>✓</td><td>Pronoun-to-project from prior turn.</td></tr><tr><td>4</td><td>✓</td><td>Missing referent → stop-and-ask, the prompt&#39;s v2 failure case.</td></tr><tr><td>5</td><td>✓</td><td>All four slots filled.</td></tr><tr><td>6</td><td>✓</td><td>Standard user-lookup with dialing-menu fallback.</td></tr><tr><td>7</td><td>⚠️</td><td>Requires capability A (date submodule).</td></tr><tr><td>8</td><td>⚠️</td><td>Requires capability B (missing-param annotation).</td></tr><tr><td>9</td><td>⚠️</td><td>Same as row 8 — missing project_name.</td></tr><tr><td>10</td><td>✓</td><td><strong>Per-verb preposition routing — table earns its keep here.</strong></td></tr><tr><td>11</td><td>✓</td><td>Requires capability C (structured history log).</td></tr><tr><td>12</td><td>✓</td><td>Ambiguous lookup → typed dialing menu.</td></tr></tbody></table><p><strong>No row scored ✗.</strong> Every scenario is expressible in the architecture. Three required capabilities (A, B, C) surfaced; all three are bounded chunks of work.</p><h2 id="required-capabilities-must-be-planned-into-phase-1" tabindex="-1">Required capabilities (must be planned into Phase 1) <a class="header-anchor" href="#required-capabilities-must-be-planned-into-phase-1" aria-label="Permalink to &quot;Required capabilities (must be planned into Phase 1)&quot;">​</a></h2><ul><li><p><strong>A. Date-resolution submodule.</strong> <code>lib/date-resolver.js</code>. Inputs: bare weekday names, <code>today</code>/<code>yesterday</code>/<code>tomorrow</code>, ISO dates, &quot;last Monday&quot;, relative phrases. Output: ISO date. Per-verb policy: logging defaults to most recent past; project deadlines default to next future.</p></li><li><p><strong>B. Missing-required-param annotation, dialing-menu-first.</strong> The pre-resolved block declares <code>MISSING &lt;slot&gt;</code> together with a numbered menu of the most plausible candidate values and a final <code>something else — let me try again with more detail</code> escape hatch. Freeform asks are reserved for slots with no plausible enumeration (hours, dollar amounts). This replaces the dozens of prompt-side rules that currently enumerate required fields per verb — one general affordance, table-driven. See &quot;Resolved decisions Q4&quot; below for the per-slot menu strategy.</p></li><li><p><strong>C. Structured conversation-history log.</strong> The pronoun-context scan needs to read a typed event log, not a free-text summary. Pre-flight: confirm <code>09. Conversations</code> (or its successor) preserves entity references with type tags, or extend it before Phase 1 ships. Without this, pronouns can&#39;t resolve to typed entities deterministically. See <code>index.js</code> summary storage path. <strong>Implemented (issue #734):</strong> <code>conversations.entities</code> is populated from both tool <em>inputs</em> (<code>ENTITY_PARAM_MAP</code> — write tools) and tool <em>outputs</em> (<code>ENTITY_OUTPUT_MAP</code> — read tools). Read tools like <code>get_project_info</code> and <code>get_project_assignments</code> now record the PM name and project name from their result so pronouns in the next turn resolve correctly. Generic list tools (<code>list_projects</code>, <code>list_users</code>) are intentionally excluded to avoid polluting the entity set with unrelated names.</p></li><li><p><strong>D. Permission-gated auto-creation.</strong> Before the resolver emits any <code>side_effects: [&quot;X will be auto-created&quot;]</code> declaration, it must check that the requesting user holds the permission required for the equivalent <code>create_X</code> tool. Failure path: drop the auto-create plan; emit a <code>MISSING X</code> annotation per capability B (menu of existing entries + <code>something else</code> escape hatch that includes an &quot;ask an Owner to create it first&quot; message when the user lacks permission). This applies symmetrically to client / user / discipline / task auto-creation. The check uses the same permission tables that gate the direct <code>create_X</code> tool calls in <code>mcp-server.js</code> — no new permission model, just consistent application of the existing one.</p></li></ul><h2 id="failure-modes-discovered" tabindex="-1">Failure modes discovered <a class="header-anchor" href="#failure-modes-discovered" aria-label="Permalink to &quot;Failure modes discovered&quot;">​</a></h2><ol><li><p><strong>Project name with embedded <code>for</code> token</strong> — <code>&quot;Create project For The Win for Acme&quot;</code>. The boundary parser would stop at the first <code>for</code>. <strong>Decision (Q2): right-greedy matching is the policy</strong> — the parser takes the <em>rightmost</em> <code>for [single-token-or-known-client]</code> as the client slot, and everything to the left of that as the project name. Quote enforcement is rejected because VERA&#39;s UX target is voice-to-text, which strips quotes. When right-greedy still gets it wrong (rare), Claude catches it in the confirmation paraphrase and the user corrects it before the tool runs.</p></li><li><p><strong>Project type aliases</strong> — users say <code>T&amp;M</code>, <code>time and materials</code>, <code>T and M</code>, <code>t&amp;m</code>, etc. Need an alias table per project type. Bounded; no architectural issue.</p></li><li><p><strong>Task aliases</strong> — <code>dev</code> = <code>Development</code>, <code>design</code> = <code>Design</code>, <code>qa</code> = <code>QA</code>. Same as above. Per-tenant if tenants use custom tasks.</p></li><li><p><strong>Ambiguous referent across types</strong> — <code>&quot;archive Acme&quot;</code> where <code>Acme</code> is both a client and a project. Resolver emits a typed dialing menu: &quot;Did you mean the <em>client</em> Acme or the <em>project</em> Acme?&quot; Already handled by capability C&#39;s typed history.</p></li><li><p><strong>Date phrases the submodule doesn&#39;t recognise</strong> — <code>&quot;next Friday after the holiday&quot;</code>. Submodule emits <code>MISSING date — couldn&#39;t parse &quot;...&quot;</code> and falls through to ask-and-stop. <strong>Important: a date-resolver that silently returns &quot;today&quot; when it can&#39;t parse is the worst possible failure mode.</strong></p></li></ol><h2 id="observability-requirements-per-tom-—-non-negotiable" tabindex="-1">Observability requirements (per Tom — non-negotiable) <a class="header-anchor" href="#observability-requirements-per-tom-—-non-negotiable" aria-label="Permalink to &quot;Observability requirements (per Tom — non-negotiable)&quot;">​</a></h2><p>Every annotation the resolver emits must be reproducible from a log. Concretely, before Phase 1 implementation begins, the design must specify:</p><ul><li>Where the annotation log lives (filesystem? Postgres table? structured stdout?).</li><li>The schema for one log entry: <code>{message_id, tenant_id, raw_message, verb_extracted, slots, resolutions, fallthrough_reason}</code>.</li><li>The Slack command that lets a user retrieve their last annotation (<code>!debug last</code>).</li><li>The retention window.</li></ul><p>See follow-up comment on RFC #654 for the full per-phase observability checklist.</p><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to &quot;Verdict&quot;">​</a></h2><p><strong>Architecture survives the spike.</strong> Every manual-test row is expressible. Three required capabilities (A, B, C) are flagged with clear scope.</p><p>Recommended next step: open a Phase 1 implementation issue against #654 with the verb-context table from this doc as the spec, capabilities A/B/C as explicit subtasks, and observability as a non-negotiable deliverable.</p><p><strong>Not recommended:</strong> start coding directly from the RFC without first writing the verb-context table into a code asset (e.g. <code>lib/verb-context-table.js</code> with one row per verb). Drift between code and prose is exactly the failure mode that bloated the prompt.</p><h2 id="open-questions-for-review" tabindex="-1">Open questions for review <a class="header-anchor" href="#open-questions-for-review" aria-label="Permalink to &quot;Open questions for review&quot;">​</a></h2><ol><li><strong>Auto-create on <code>create_project</code>?</strong> The walkthrough assumed <code>findOrCreateClient</code> semantics are preserved (i.e. typing a new client name in <code>create_project</code> auto-creates the client). Confirm this is still desired. Alternative: require an explicit <code>create_client</code> first.</li><li><strong><code>for</code> token in project names.</strong> Should the table enforce quotes when a project name contains a reserved preposition, or is right-greedy parsing acceptable?</li><li><strong>Per-tenant verb aliases.</strong> Some agencies say &quot;log time&quot; as &quot;track time&quot; or &quot;record time&quot;. Is alias normalisation in scope for Phase 1, or punted to Phase 3?</li><li><strong>Confidence threshold for fall-through to Claude.</strong> When the extractor has &lt;100% confidence (e.g. ambiguous noun boundary), should it emit a &quot;low-confidence — Claude please verify&quot; annotation, or always commit to its best guess?</li></ol><h2 id="resolved-decisions-review-pass-2026-05-16" tabindex="-1">Resolved decisions (review pass, 2026-05-16) <a class="header-anchor" href="#resolved-decisions-review-pass-2026-05-16" aria-label="Permalink to &quot;Resolved decisions (review pass, 2026-05-16)&quot;">​</a></h2><p>The four open questions above were resolved during review. Recording the decisions here; the upstream sections of this doc (verb-context table, capability B, failure modes) have been amended where these decisions force a change.</p><h3 id="q1-→-yes-auto-create-—-but-the-paraphrase-must-surface-it-and-the-permission-must-be-checked" tabindex="-1">Q1 → Yes, auto-create — but the paraphrase must surface it, AND the permission must be checked <a class="header-anchor" href="#q1-→-yes-auto-create-—-but-the-paraphrase-must-surface-it-and-the-permission-must-be-checked" aria-label="Permalink to &quot;Q1 → Yes, auto-create — but the paraphrase must surface it, AND the permission must be checked&quot;">​</a></h3><p>When <code>create</code> precedes a <code>for X</code> project grammar and <code>X</code> doesn&#39;t match an existing client, auto-create <code>X</code> as a client. <strong>The annotation must explicitly declare the auto-creation as a side-effect</strong>, and Claude&#39;s confirmation paraphrase must surface it to the user before the tool runs. Users should never discover that a client was created by accident; the confirmation step is where they catch it.</p><p>This adds a new requirement to the annotation schema: a <code>side_effects</code> field listing any entities the tool call will create or modify beyond the primary action.</p><p><strong>Permission gate (Q1 refinement):</strong> the resolver MUST NOT emit an auto-create side effect unless the requesting user holds the permission required for the equivalent <code>create_X</code> tool. A User has no <code>create_client</code> permission, so a <code>create_project for [unknown client]</code> request from a User must not silently provision the client. Instead, fall through to capability B: emit <code>MISSING client_name</code> with a dialing menu of existing clients the User can pick from, plus a <code>something else</code> option that returns a clear &quot;you don&#39;t have permission to create new clients — ask [list of owners] to add this client first&quot; response.</p><p>This generalises to <strong>every</strong> auto-creation: clients, users (auto-register on first DM), disciplines, tasks. The principle: an auto-create side effect always inherits the permission of the corresponding <code>create_X</code> tool, with no exceptions for &quot;convenience&quot;. See capability D below.</p><h3 id="q2-→-right-greedy-parsing-no-quote-enforcement" tabindex="-1">Q2 → Right-greedy parsing, no quote enforcement <a class="header-anchor" href="#q2-→-right-greedy-parsing-no-quote-enforcement" aria-label="Permalink to &quot;Q2 → Right-greedy parsing, no quote enforcement&quot;">​</a></h3><p>Quotes are nice but not enforceable. VERA users are encouraged to interact via voice-to-text, which strips quote characters. Any rule that requires quotes degrades the UX for voice users.</p><p><strong>Decision:</strong> the boundary parser uses right-greedy matching with the boundary-word list. If a project name genuinely contains a reserved preposition (<code>&quot;For The Win&quot;</code>), the parser will get it wrong and Claude will catch it in the paraphrase step. That&#39;s an acceptable failure mode — users can correct it during confirmation. Forcing quotes is a worse failure mode because it punishes the voice-first UX VERA is designed for.</p><p>Failure mode #1 in the upstream section is updated to commit to right-greedy.</p><h3 id="q3-→-verb-aliases-normalised-in-phase-1-paraphrase-always-uses-the-canonical-verb" tabindex="-1">Q3 → Verb aliases normalised in Phase 1, paraphrase always uses the canonical verb <a class="header-anchor" href="#q3-→-verb-aliases-normalised-in-phase-1-paraphrase-always-uses-the-canonical-verb" aria-label="Permalink to &quot;Q3 → Verb aliases normalised in Phase 1, paraphrase always uses the canonical verb&quot;">​</a></h3><p>Specifically: <code>log</code>, <code>track</code>, and <code>record</code> all coerce to the canonical verb <code>log</code> for <code>log_time</code>. This normalisation happens at extraction time, and the paraphrase Claude shows the user uses only the canonical verb regardless of which alias the user typed. The user&#39;s input is preserved in the audit log, but the confirmation message is consistent.</p><p>Other alias families to plan for in the Phase 1 table (extend before implementation starts):</p><ul><li><code>create</code> / <code>add</code> / <code>set up</code> / <code>start</code> → <code>create</code></li><li><code>allocate</code> / <code>assign hours</code> → <code>allocate</code> (note: distinct from <code>assign</code> which is PM assignment)</li><li><code>cancel</code> / <code>kill</code> / <code>stop</code> → <code>cancel</code></li><li><code>archive</code> / <code>hide</code> → <code>archive</code></li></ul><p>This is in scope for Phase 1, not punted. The alias table lives next to the verb-context table in the same file.</p><h3 id="q4-→-dialing-menu-of-likely-options-with-a-something-else-escape-hatch" tabindex="-1">Q4 → Dialing menu of likely options, with a <code>something else</code> escape hatch <a class="header-anchor" href="#q4-→-dialing-menu-of-likely-options-with-a-something-else-escape-hatch" aria-label="Permalink to &quot;Q4 → Dialing menu of likely options, with a `something else` escape hatch&quot;">​</a></h3><p>Replaces the original capability B framing. Instead of &quot;MISSING X — ask the user&quot; as freeform text, the annotation emits a <strong>dialing menu of the most plausible values plus a final <code>something else / please try again with more detail</code> option</strong>. The user replies with a digit; Claude resumes the action with the selection.</p><p>This is a significant refinement to capability B. Concretely, per slot type:</p><table tabindex="0"><thead><tr><th>Slot</th><th>Menu strategy</th></tr></thead><tbody><tr><td><code>project_type</code></td><td>6 enumerated options + something else</td></tr><tr><td><code>target_type</code> for ambiguous archive/rename</td><td>each candidate type + something else</td></tr><tr><td><code>project_name</code> (missing)</td><td>top 5 recently-touched projects for this user + something else</td></tr><tr><td><code>client_name</code> (missing)</td><td>top 5 recently-touched clients for this tenant + something else</td></tr><tr><td><code>user_name</code> (missing)</td><td>active users this tenant the requesting user has recently mentioned + something else</td></tr><tr><td><code>task_name</code> (missing)</td><td>tasks enabled on the resolved project + something else</td></tr><tr><td><code>hours</code> (missing)</td><td>no menu — must ask freeform (no plausible enumeration)</td></tr><tr><td><code>date</code> (missing)</td><td>menu of <code>today</code>, <code>yesterday</code>, the last weekday, last week + something else</td></tr><tr><td><code>contract_value</code> / <code>agreed_amount</code> (missing)</td><td>no menu — freeform</td></tr></tbody></table><p>The <code>something else</code> option always reads as: <code>&quot;None of these — let me try again with more detail.&quot;</code> It clears any partial state and re-enters the conversation. This is the affordance that lets the deterministic resolver fail gracefully without trapping the user.</p><p>Capability B in the upstream section is updated to reflect this menu-first design.</p>',189)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
